#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int minimumFinishTimeWithCooldown(std::vector<int>& tasks, int workers, int cooldown) {
        int low = *std::max_element(tasks.begin(), tasks.end());
        int high = std::accumulate(tasks.begin(), tasks.end(), 0) + tasks.size() * cooldown;

        auto canFinish = [&](int limit) {
            int used = 1, cur = 0;
            bool isFirst = true;
            for (int t : tasks) {
                int cost = isFirst ? t : t + cooldown;
                if (cur + cost > limit) {
                    used++;
                    cur = t;
                    isFirst = false;
                    if (used > workers || cur > limit) return false;
                } else {
                    cur += cost;
                    isFirst = false;
                }
            }
            return true;
        };

        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canFinish(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int minimumFinishTimeWithCooldown(int[] tasks, int workers, int cooldown) {
        int low = 0, high = 0;
        for (int t : tasks) {
            low = Math.max(low, t);
            high += t + cooldown;
        }
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            int used = 1, cur = 0;
            boolean isFirst = true;
            boolean ok = true;
            for (int t : tasks) {
                int cost = isFirst ? t : t + cooldown;
                if (cur + cost > mid) {
                    used++;
                    cur = t;
                    isFirst = false;
                    if (used > workers || cur > mid) {
                        ok = false;
                        break;
                    }
                } else {
                    cur += cost;
                    isFirst = false;
                }
            }
            if (ok) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

function minimumFinishTimeWithCooldown(tasks, workers, cooldown) {
    let low = Math.max(...tasks);
    let high = tasks.reduce((a, b) => a + b + cooldown, 0);
    let ans = high;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let used = 1, cur = 0, isFirst = true, ok = true;
        for (const t of tasks) {
            const cost = isFirst ? t : t + cooldown;
            if (cur + cost > mid) {
                used++;
                cur = t;
                isFirst = false;
                if (used > workers || cur > mid) {
                    ok = false;
                    break;
                }
            } else {
                cur += cost;
                isFirst = false;
            }
        }
        if (ok) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
}
